const START_DATE = '2026-06-30';
const today = new Date();
today.setHours(0, 0, 0, 0);
const formatDate = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const todayStr = formatDate(today);
const startDate = new Date(START_DATE + 'T00:00:00');
const dayNumber = Math.max(1, Math.round((today - startDate) / 86400000) + 1);
const targetPace = Math.round(dayNumber / 180 * 300);

const logs = $('Read Log1').all().map(i => i.json);
const questions = $('Read Questions1').all().map(i => i.json);
const days = $('Read Days1').all().map(i => i.json);

const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
const sevenDaysAgoStr = sevenDaysAgo.toISOString().split('T')[0];

const weekLogs = logs.filter(l => l.Timestamp && l.Timestamp >= sevenDaysAgoStr);
const newCount = weekLogs.filter(l => l.Type === 'New').length;
const reviewCount = weekLogs.filter(l => l.Type === 'Review').length;

let missedDays = 0;
for (let d = new Date(sevenDaysAgo); d < today; d.setDate(d.getDate() + 1)) {
  const ds = d.toISOString().split('T')[0];
  const dayRow = days.find(r => r.Date === ds);
  if (!dayRow || dayRow.Logged !== 'Y') missedDays++;
}

const total = questions.filter(q => q.Status !== 'Dropped').length;

const backlogCount = questions.filter(q =>
  q.Status === 'Active' && q.NextReviewDate && q.NextReviewDate < todayStr
).length;

const patternMap = {};
for (const log of logs) {
  const q = questions.find(qu => qu.Problem === log.Question);
  const pat = q ? (q.Pattern || 'Unknown') : 'Unknown';
  if (!patternMap[pat]) patternMap[pat] = [];
  patternMap[pat].push(parseInt(log.Confidence) || 3);
}

let strongest = 'N/A', weakest = 'N/A', strongestAvg = 0, weakestAvg = 6;
for (const [pat, confs] of Object.entries(patternMap)) {
  const avg = confs.reduce((a, b) => a + b, 0) / confs.length;
  if (avg > strongestAvg) { strongest = pat; strongestAvg = avg; }
  if (avg < weakestAvg) { weakest = pat; weakestAvg = avg; }
}
strongestAvg = strongestAvg.toFixed(1);
weakestAvg = weakestAvg.toFixed(1);

const statsText = 'Day ' + dayNumber + '/180\n'
  + 'New this week: ' + newCount + ', Reviews this week: ' + reviewCount + '\n'
  + 'Missed days this week: ' + missedDays + '\n'
  + 'Cumulative solved: ' + total + '/300 (target pace: ' + targetPace + ')\n'
  + 'Review backlog (overdue): ' + backlogCount + '\n'
  + 'Strongest pattern: ' + strongest + ' (avg confidence ' + strongestAvg + ')\n'
  + 'Weakest pattern: ' + weakest + ' (avg confidence ' + weakestAvg + ')';

const prompt = 'You write a short, honest weekly status update for someone doing a 180-day, 300-question DSA prep routine. Be direct, not hypey. Max 5 lines. Flag the review backlog explicitly if it is above 5. If pace is behind target, say so plainly without softening it.\n\nStats:\n' + statsText;

return [{ json: { statsText: statsText, geminiBody: { contents: [{ parts: [{ text: prompt }] }] } } }];

const response = $input.first().json;
let report = '';
if (response.text) {
  report = response.text.trim();
} else {
  report = '⚠️ Could not generate weekly report. Raw stats:\n' + $('Compute Stats1').item.json.statsText;
}
return [{ json: { report: report } }];
